-- Auth SQL generated by Better Auth 1.7.14; retained from the reviewed proof.
create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null);

create table "session" ("id" text not null primary key, "expiresAt" date not null, "token" text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);

create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);

create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);

create index "session_userId_idx" on "session" ("userId");

create index "account_userId_idx" on "account" ("userId");

create index "verification_identifier_idx" on "verification" ("identifier");

CREATE TABLE owner_profile (
 user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE RESTRICT,
 display_name TEXT NOT NULL CHECK(length(display_name) BETWEEN 1 AND 200)
);
CREATE TABLE place (
 id TEXT PRIMARY KEY, name_km TEXT NOT NULL, name_en TEXT NOT NULL,
 province TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'accommodation',
 publication TEXT NOT NULL DEFAULT 'draft' CHECK(publication IN ('draft','review','published','paused'))
);
CREATE INDEX place_discovery ON place(publication,province,category);
CREATE TABLE property (
 id TEXT PRIMARY KEY REFERENCES place(id) ON DELETE RESTRICT,
 owner_id TEXT NOT NULL REFERENCES owner_profile(user_id) ON DELETE RESTRICT,
 timezone TEXT NOT NULL DEFAULT 'Asia/Phnom_Penh' CHECK(timezone='Asia/Phnom_Penh'),
 checkin_time TEXT NOT NULL CHECK(checkin_time GLOB '[0-2][0-9]:[0-5][0-9]' AND checkin_time<'24:00'),
 checkout_time TEXT NOT NULL CHECK(checkout_time GLOB '[0-2][0-9]:[0-5][0-9]' AND checkout_time<'24:00'),
 policy_version TEXT NOT NULL, policy_text TEXT NOT NULL CHECK(length(policy_text) BETWEEN 1 AND 10000),
 terms_version TEXT NOT NULL,
 charges_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(charges_json) AND json_type(charges_json)='array'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0)
);
CREATE INDEX property_owner ON property(owner_id);
CREATE TABLE room_type (
 id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES property(id) ON DELETE RESTRICT,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
 adult_capacity INTEGER NOT NULL CHECK(typeof(adult_capacity)='integer' AND adult_capacity BETWEEN 1 AND 100),
 child_capacity INTEGER NOT NULL CHECK(typeof(child_capacity)='integer' AND child_capacity BETWEEN 0 AND 100),
 total_capacity INTEGER NOT NULL CHECK(typeof(total_capacity)='integer' AND total_capacity BETWEEN 1 AND 100),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 UNIQUE(id,property_id)
);
CREATE INDEX room_property ON room_type(property_id,active);
CREATE TABLE inventory_night (
 room_type_id TEXT NOT NULL REFERENCES room_type(id) ON DELETE RESTRICT,
 night TEXT NOT NULL CHECK(length(night)=10 AND date(night,'+0 days') IS NOT NULL AND date(night,'+0 days')=night),
 capacity INTEGER NOT NULL CHECK(typeof(capacity)='integer' AND capacity BETWEEN 0 AND 10000),
 blocked INTEGER NOT NULL DEFAULT 0 CHECK(typeof(blocked)='integer' AND blocked BETWEEN 0 AND 10000),
 reserved INTEGER NOT NULL DEFAULT 0 CHECK(typeof(reserved)='integer' AND reserved BETWEEN 0 AND 10000),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(room_type_id,night), CHECK(blocked+reserved<=capacity)
);
CREATE TABLE nightly_rate (
 room_type_id TEXT NOT NULL REFERENCES room_type(id) ON DELETE RESTRICT,
 night TEXT NOT NULL CHECK(length(night)=10 AND date(night,'+0 days') IS NOT NULL AND date(night,'+0 days')=night),
 unit_cents INTEGER NOT NULL CHECK(typeof(unit_cents)='integer' AND unit_cents BETWEEN 0 AND 100000000),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(room_type_id,night)
);

-- Generated for Better Auth database-backed abuse controls (1.7.14).
create table "rateLimit" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);
